mapper.select:
SELECT clazz.*, emp.name AS masterName, (CASE WHEN NOW() < clazz.begin_date THEN 1 WHEN NOW() > clazz.end_date THEN 3 ELSE 2 END) AS status FROM clazz LEFT JOIN emp ON clazz.master_id = emp.id
AND clazz.name LIKE CONCAT('%', #{name}, '%')
AND clazz.begin_date >= #{beginDate}
AND clazz.begin_date <= #{endDate}
ORDER BY clazz.id

