) VALUES (
#{clazz.name}, #{clazz.room}, #{clazz.beginDate}, #{clazz.endDate},
#{clazz.masterId}, #{clazz.subject}, #{clazz.createTime}, #{clazz.updateTime}
)

mapper.select:
SELECT COUNT(*)
FROM student
WHERE clazz_id = #{id}
